text(await tools.exec_command({cmd:"python - <<'PY'
import csv, math, re, statistics
from collections import defaultdict
from datetime import datetime, timezone

num=r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)'
def amount(raw):
    raw=raw.strip()
    if not raw:
        return math.nan
    sign=-1 if ('CR' in raw or '-' in raw or (raw[0]=='(' and raw[-1]==')')) else 1
    text=raw.replace('C1','').replace('C2','')
    text=''.join(c for c in text if c.isdigit() or c in ',.')
    if not text:
        return math.nan
    separators={c for c in text if c in ',.'}
    decimal=None
    if len(separators)==2:
        decimal=max(text.rfind(','),text.rfind('.'))
    elif separators:
        last=text.rfind(next(iter(separators)))
        if len(text)-last-1==2:
            decimal=last
    if decimal is None:
        cleaned=text.replace(',','').replace('.','')
    else:
        cleaned=text[:decimal].replace(',','').replace('.','')+'.'+text[decimal+1:]
    return sign*float(cleaned)

def note_number(notes, field, suffix='', default=0):
    match=re.search(r'\b'+field+'=('+num+')'+suffix,notes)
    return float(match[1]) if match else default

chosen={}
with open('/app/dataset/data.csv',newline='') as f:
    for order,row in enumerate(csv.DictReader(f)):
        base=amount(row['amount_str'])
        adj=note_number(row['notes'],'adj','%')/100
        fee=note_number(row['notes'],'fee')
        waive=bool(re.search(r'\bwaive=true\b',row['notes'],re.I))
        net=math.nan if math.isnan(base) else (0.0 if waive else base*(1+adj)+fee)
        time=datetime.fromisoformat(row['event_time']) if row['event_time'] else None
        item_match=re.search(r'\bitems=([+-]?\d+)',row['notes'])
        items=max(1,int(item_match[1])) if item_match else 1
        row.update(net=net,time=time,items=items,order=order)
        rank=(time or datetime.min.replace(tzinfo=timezone.utc),not math.isnan(net),-order)
        rid=row['record_id']
        if rid not in chosen or rank>chosen[rid][0]:
            chosen[rid]=(rank,row)

start=datetime.fromisoformat('2025-10-01T00:00:00+00:00')
end=datetime.fromisoformat('2025-12-31T23:59:59+00:00')
groups=defaultdict(list)
for _,row in chosen.values():
    if row['time'] is not None and start<=row['time']<=end and row['channel'].strip().casefold()!='phone' and math.isfinite(row['net']):
        groups[(row['region'],row['time'].strftime('%Y-%m'))].append(row)
ranked=[]
for key,rows in groups.items():
    med=statistics.median(r['net'] for r in rows)
    mad=statistics.median(abs(r['net']-med) for r in rows)
    for r in rows:
        r['z']=0 if mad==0 else .6745*(r['net']-med)/mad
        r['score']=abs(r['z'])*math.log1p(r['items'])
        ranked.append(r)
ranked.sort(key=lambda r:(-r['score'],-abs(r['z']),-r['time'].timestamp(),r['record_id']))
expected=['R00226','R00117','R00125','R00268','R00243','R00109','R00002','R00052','R00024','R00196']
actual=[r['record_id'] for r in ranked[:10]]
assert actual==expected,(actual,expected)
print('Independent calculation agrees:',actual)
print('Eligible:',len(ranked),'Groups:',len(groups))
for r in ranked[:10]:
    print(r['record_id'],format(r['score'],'.12f'))
